ee:message.ee:set-payload:
%dw 2.0
output application/json

var source = payload
var cust = source.customer
var person = cust.person// 1. Diccionario de códigos postales para una búsqueda rápida y limpia
var codigoPostalMap = {
    "BOGOTA D.C.": "F00100001",
    "BOGOTA":      "F00100001",
    "CHIA":        "F01800001",
    "SOACHA":      "F08600001",
    "TOCANCIPA":   "F10000001",
    "MADRID":      "F05600001",
    "MOSQUERA":    "F05900001",
    "FACATATIVA":  "F02700001",
    "LA CALERA":   "F04900001",
    "FUNZA":       "F03001001"
}

// 2. Función para obtener la Localidad
fun obtenerLocalidad(ciudad: String) = 
    ciudad match {
        case "BOGOTA D.C." -> "BOGOTA"
        else               -> upper(ciudad) // Para CHIA, SOACHA, etc., devuelve el mismo nombre
    }

// 3. Función para obtener el Código Postal
fun obtenerCodigoPostal(ciudad: String) = 
    codigoPostalMap[upper(ciudad)] default "F00000000" // Código por defecto si la ciudad no existe


fun homologarTipoDocumento(tipo: String) = 
    tipo match {
        case "CC"      -> "1"
        case "NIT"     -> "2"
        case "NIT_EXT" -> "3"
        case "CE"      -> "4"
        case "TI"      -> "5"
        case "N/A"     -> "6"
        case "PP"      -> "7"
        case "PEP"     -> "8"
        case "PPT"     -> "9"
        else           -> "0" // Valor por defecto si no coincide ninguno
    }


---
{
  "CaptureCustomerAndProducts": {
    "CaptureType": "External",
    "Customer": {
      "AddressList": {
        "UrbanPropertyAddress": {
          "city": cust.address.city,
          "streetNrFirst": cust.address.streetNumber,
          "streetName": cust.address.streetName,
          "locality": obtenerLocalidad(upper(cust.address.city)),
          "postCode": obtenerCodigoPostal(cust.address.city)
        }
      },
      "ContactableVia": {
        "ContactMedium": [
          {
            "number": cust.contact.phone,
            "type": "HOME_PHONE"
          }
        ]
      },
      "IndividualRole": {
        "aliveDuring": {
          "startDateTime": person.birthDate
        },
        "partyId": source.product.partyId,
        "IdentifiedBy": {
          "IndividualIdentifications": [
            {
              "scan": homologarTipoDocumento(upper(person.identification."type")),
              "cardNr": person.identification.number
            },
            {
              "scan": source.credentials.username,
              "password": source.credentials.password
            }
          ]
        },
        "NameUsing": {
          "IndividualNames": {
            "givenNames": person.firstName,
            "familyNames": person.lastName
          }
        }
      }
    },
    "CustomerOrder": {
      "Items": [
        {
          "CustomerProduct": {
            "productKey": source.product.id
          }
        },
        {
          "CustomerProduct": {
            "productKey": 338
          }
        }
      ]
    }
  }
}

%dw 2.0
output application/json

// Variables de control para facilitar el acceso
var response = payload.CaptureCustomerAndProductsResponse
var result = response.CaptureCustomerAndProductsResult
var metadata = response.ResponseMetadata
var requestMeta = metadata.requestMetadata
---
{
  // El código lo manejamos como String según tu destino
  "code": if (metadata.returnCode == "0") "200" else "500",

  "message": if (metadata.returnCode == "0") "Subscriber created successfully" 
             else (metadata.returnMessage default "Error creating subscriber"),

  "data": {
    "customerId": result.Customer.ID,
    "partyRoleId": result.Customer.partyRoleId
  },

  "responseMetadata": {
    "requestMetadata": {
      "systemId": requestMeta.systemID,
      "sender": {
        "country": requestMeta.sender.country,
        "milestone": requestMeta.sender.milestone
      },
      "requestId": requestMeta.requestID,
      "userId": requestMeta.userID
    },
    "returnCode": metadata.returnCode,
    "returnMessage": metadata.returnMessage
  }
}
